import { test, expect, Page } from '@playwright/test';

test.describe('Async PDF Generation Download', () => {
  let page: Page;
  const TEST_TIMEOUT = 30000;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');
  });

  test('should generate and download PDF when ready', async () => {
    // Click the generate PDF button
    const generateButton = page.getByRole('button', { name: /generate pdf/i });
    await expect(generateButton).toBeVisible();

    // Start waiting for download before clicking
    const downloadPromise = page.waitForEvent('download');
    await generateButton.click();

    // Wait for the download to complete
    const download = await downloadPromise;

    // Verify the download filename
    expect(download.suggestedFilename()).toMatch(/\.pdf$/);

    // Verify the file was downloaded successfully
    const path = await download.path();
    expect(path).toBeTruthy();
  });

  test('should show loading state during PDF generation', async () => {
    // Click the generate PDF button
    const generateButton = page.getByRole('button', { name: /generate pdf/i });
    await generateButton.click();

    // Verify loading indicator appears
    const loadingIndicator = page.getByRole('status', { name: /generating/i });
    await expect(loadingIndicator).toBeVisible({ timeout: 5000 });

    // Verify loading indicator disappears after generation completes
    await expect(loadingIndicator).not.toBeVisible({ timeout: TEST_TIMEOUT });
  });

  test('should display success message after PDF download', async () => {
    // Start listening for downloads
    const downloadPromise = page.waitForEvent('download');

    // Click generate button
    const generateButton = page.getByRole('button', { name: /generate pdf/i });
    await generateButton.click();

    // Wait for download to complete
    await downloadPromise;

    // Verify success message appears
    const successMessage = page.getByRole('status', { name: /pdf generated successfully/i });
    await expect(successMessage).toBeVisible({ timeout: TEST_TIMEOUT });
  });

  test('should handle PDF generation errors gracefully', async () => {
    // Navigate to error scenario
    const errorButton = page.getByRole('button', { name: /generate with error/i });

    if (await errorButton.isVisible()) {
      await errorButton.click();

      // Verify error message appears
      const errorMessage = page.getByRole('alert');
      await expect(errorMessage).toBeVisible({ timeout: TEST_TIMEOUT });

      // Verify error message contains relevant text
      await expect(errorMessage).toContainText(/error|failed/i);
    }
  });

  test('should allow multiple sequential PDF downloads', async () => {
    const generateButton = page.getByRole('button', { name: /generate pdf/i });

    // First PDF generation
    let downloadPromise = page.waitForEvent('download');
    await generateButton.click();
    let download = await downloadPromise;
    expect(download.suggestedFilename()).toMatch(/\.pdf$/);

    // Wait for UI to reset
    await page.waitForTimeout(1000);

    // Second PDF generation
    downloadPromise = page.waitForEvent('download');
    await generateButton.click();
    download = await downloadPromise;
    expect(download.suggestedFilename()).toMatch(/\.pdf$/);
  });

  test('should update progress during PDF generation', async () => {
    const generateButton = page.getByRole('button', { name: /generate pdf/i });
    await generateButton.click();

    // Check for progress indicator
    const progressBar = page.getByRole('progressbar');

    if (await progressBar.isVisible()) {
      // Verify progress bar is visible during generation
      await expect(progressBar).toBeVisible();

      // Wait for progress to complete
      await expect(progressBar).not.toBeVisible({ timeout: TEST_TIMEOUT });
    }
  });

  test('should disable generate button during PDF generation', async () => {
    const generateButton = page.getByRole('button', { name: /generate pdf/i });

    // Start download process
    const downloadPromise = page.waitForEvent('download');
    await generateButton.click();

    // Verify button is disabled during generation
    await expect(generateButton).toBeDisabled();

    // Wait for download to complete
    await downloadPromise;

    // Verify button is re-enabled after generation
    await expect(generateButton).toBeEnabled({ timeout: TEST_TIMEOUT });
  });
});
